<?php
require_once __DIR__.'/config/app.php';require_login();$pdo=db();$folders=$pdo->query('SELECT id_folder,nama_folder FROM folder ORDER BY nama_folder')->fetchAll();$folder=(int)($_GET['folder']??0);$month=(int)($_GET['bulan']??0);$year=(int)($_GET['tahun']??date('Y'));$where=[];$params=[];if($folder){$where[]='d.id_folder=?';$params[]=$folder;}if($month>=1&&$month<=12){$where[]='MONTH(d.tanggal_upload)=?';$params[]=$month;}if($year>=2000&&$year<=2100){$where[]='YEAR(d.tanggal_upload)=?';$params[]=$year;}$sql='SELECT d.*,f.nama_folder FROM dokumen d JOIN folder f ON f.id_folder=d.id_folder';if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY f.nama_folder,d.tanggal_upload DESC';$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$sum=array_sum(array_column($rows,'jumlah_arsip'));$title='Laporan';require __DIR__.'/includes/header.php';?>
<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">Laporan Arsip</h1><button onclick="window.print()" class="btn btn-outline-primary no-print">Cetak laporan</button></div><div class="card mb-3 no-print"><div class="card-body"><form class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label">Folder</label><select class="form-select" name="folder"><option value="0">Semua folder</option><?php foreach($folders as $f):?><option value="<?=$f['id_folder']?>" <?=$folder===$f['id_folder']?'selected':''?>><?=e($f['nama_folder'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Bulan</label><select class="form-select" name="bulan"><option value="0">Semua bulan</option><?php foreach(range(1,12) as $m):?><option value="<?=$m?>" <?=$month===$m?'selected':''?>><?=e(date('F',mktime(0,0,0,$m,1)))?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Tahun</label><input class="form-control" type="number" min="2000" max="2100" name="tahun" value="<?=$year?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Tampilkan</button></div></form></div></div><div class="card"><div class="card-body"><h2 class="h5">Rekap arsip</h2><p class="text-muted">Dihasilkan <?=e(date('d/m/Y H:i'))?> · Total jumlah arsip: <strong><?=$sum?></strong></p><div class="table-responsive"><table class="table"><thead><tr><th>Folder</th><th>Informasi</th><th>Tanggal</th><th>Jumlah</th><th>Kondisi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nama_folder'])?></td><td><?=e($r['informasi_arsip'])?></td><td><?=e($r['tanggal_upload'])?></td><td><?=$r['jumlah_arsip']?></td><td><?=e($r['kondisi_arsip'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center text-muted">Tidak ada data untuk filter ini.</td></tr><?php endif;?></tbody></table></div></div></div>
<?php require __DIR__.'/includes/footer.php';?>
